arguments.command:
cd /workspace && python3 - << 'EOF'
import json
req = json.load(open('/workspace/tmp/req.json'))
for f in req['flows'][:6]:
    kinds=f['kinds']; tmpl=bytes.fromhex(f['template']); H=len(tmpl)
    q=kinds.index('Q'); t=kinds.index('T'); N=len(f['path']); h=N-1
    for run in req['offers'][f['id']]:
        hdr=bytes.fromhex(run['header'])
        bad=[]
        for i in range(H):
            if kinds[i]=='K' and hdr[i]!=tmpl[i]: bad.append(('K',i))
        if hdr[q]>7: bad.append(('Q',hdr[q]))
        if hdr[t]<=h: bad.append(('T',hdr[t]))
        if bad: print(f['id'], run['count'], bad[:5])
print('done')
EOF
